{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "The closest analogue, ondansetron, had an absolute oral bioavailability of 0.56 (95% CI 0.52-0.62) in healthy young volunteers after 8 mg oral vs IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In healthy elderly volunteers, ondansetron absolute oral bioavailability was 0.65 (0.60-0.72), confirming high oral F in a second population.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Ondansetron oral tablet absolute bioavailability was 0.65 ± 0.06 in patients, supporting high oral bioavailability for this carbazolone chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A study in healthy subjects reported an average absolute oral bioavailability of 0.74 for ondansetron, again far above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Ondansetron is well absorbed orally with a bioavailability of approximately 60-70%, with first-pass metabolism removing only 30-40%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an ondansetron isomer, and ondansetron's absolute oral bioavailability is consistently 50-87% across multiple human studies, far above the 20% threshold. The closest analogue evidence is direct and transferable, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct bioavailability measurement exists for the exact query isomer; extrapolation from ondansetron assumes the imidazole attachment isomer does not drastically alter first-pass metabolism.",
    "No query-specific solubility or permeability data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

